/* @lc app=leetcode id=3777 lang=kotlin */ class Solution { fun ad(t: IntArray, i0: Int, d: Int) = generateSequence(i0) { it + (it and -it) }.takeWhile { it < t.size }.forEach { t[it] += d } fun qs(t: IntArray, i0: Int): Int = generateSequence(i0) { it - (it and -it) }.takeWhile { it > 0 }.sumOf { t[it] } fun minDeletions(s: String, queries: Array<IntArray>): IntArray = s.toCharArray().let { cs -> IntArray(s.length + 1).let { bit -> (0 until s.length - 1).filter { cs[it] == cs[it + 1] }.forEach { ad(bit, it + 1, 1) }.let { queries.mapNotNull { q -> if (q[0] == 1) q[1].let { j -> (if (j > 0 && cs[j - 1] == cs[j]) -1 else 1).let { d1 -> (if (j < cs.size - 1 && cs[j] == cs[j + 1]) -1 else 1).let { d2 -> (if (j > 0) ad(bit, j, d1) else Unit).let { (if (j < cs.size - 1) ad(bit, j + 1, d2) else Unit).let { cs[j] = if (cs[j] == 'A') 'B' else 'A' } } } } }.let { null } else qs(bit, q[2]) - qs(bit, q[1]) }.toIntArray() } } } }